	@Test
	void recognizerRejectsUnboundCountsDistinctGraphsAndAdditionalJoinDimensions() {
		PatternPlan left = pattern(0, 1, Term.unbound());
		PatternPlan right = pattern(1, 2, Term.unbound());
		SlotPlan join = new JoinPlan(left, right);
		assertNotNull(LmdbSparseJoinAggregatePlan.tryCreate(join, new int[] { 0, 2 }, COUNTS, null));
		assertNull(LmdbSparseJoinAggregatePlan.tryCreate(join, new int[] { 0 }, COUNTS, null));
		assertNull(LmdbSparseJoinAggregatePlan.tryCreate(join, new int[] { 0, 1 }, COUNTS, null));
		assertNull(LmdbSparseJoinAggregatePlan.tryCreate(join, new int[] { 0, 2 },
				new AggregateSpec[] { AggregateSpec.slot("count", 3, false, AggKind.COUNT) }, null));
		assertNull(LmdbSparseJoinAggregatePlan.tryCreate(join, new int[] { 0, 2 },
				new AggregateSpec[] { AggregateSpec.slot("count", 1, true, AggKind.COUNT) }, null));
		assertNull(LmdbSparseJoinAggregatePlan.tryCreate(new JoinPlan(pattern(0, 1, Term.slot(3)),
				pattern(1, 2, Term.slot(3))), new int[] { 0, 2 }, COUNTS, null));
		assertNull(LmdbSparseJoinAggregatePlan.tryCreate(new JoinPlan(left, pattern(1, 0, Term.unbound())),
				new int[] { 0, 1 }, COUNTS, null));
		assertNull(LmdbSparseJoinAggregatePlan.tryCreate(new JoinPlan(join, right), new int[] { 0, 2 }, COUNTS, null));
	}

	@Test
	void aliasAssignmentsRequireFreshTargetsAndBoundSources() {
		SlotPlan join = new JoinPlan(pattern(0, 1, Term.unbound()), pattern(1, 2, Term.unbound()));
		AggregateSpec[] aliases = { AggregateSpec.slot("count", 4, false, AggKind.COUNT) };
		SlotPlan inner = new ExtensionPlan(join, new CopyBinding[] { new CopyBinding(3, 1, 0L) });
		SlotPlan outer = new ExtensionPlan(inner, new CopyBinding[] { new CopyBinding(4, 3, 0L) });
		LmdbSparseJoinAggregatePlan plan = LmdbSparseJoinAggregatePlan.tryCreate(outer, new int[] { 0, 2 },
				aliases, null);
		assertNotNull(plan);
		assertNull(LmdbSparseJoinAggregatePlan.tryCreate(new ExtensionPlan(join,
				new CopyBinding[] { new CopyBinding(4, 3, 0L), new CopyBinding(3, 1, 0L) }),
				new int[] { 0, 2 }, aliases, null), "an alias cannot read a target before it is assigned");
		assertNull(LmdbSparseJoinAggregatePlan.tryCreate(new ExtensionPlan(join,
				new CopyBinding[] { new CopyBinding(0, 1, 0L) }), new int[] { 0, 2 }, COUNTS, null),
				"overwriting an endpoint is not the original endpoint grouping");
		NativeLmdbQuerySource source = mock(NativeLmdbQuerySource.class);
		when(source.hasCanonicalIds()).thenReturn(true);
		NativeSlotLayout layout = new NativeSlotLayout(Map.of("a", 0, "j", 1, "b", 2, "alias", 3, "copy", 4), null);
		layout.freeze(List.of("a", "j", "b", "alias", "copy"));
		RowState row = new RowState(source, layout, EmptyBindingSet.getInstance());
		try {
			assertTrue(LmdbNativeAggregateCompiler.initializeRow(row, row.base, source, layout));
			assertTrue(plan.handles(row));
			row.slots[4] = 42L;
			assertFalse(plan.handles(row), "a prebound assignment target requires ordinary extension semantics");
		} finally {
			row.closeDecodedInputs();
			row.memoryScope.close();
		}
	}

	@Test
	void noncanonicalSourcesAndBoundEntriesDecline() {
		LmdbSparseJoinAggregatePlan plan = LmdbSparseJoinAggregatePlan.tryCreate(
				new JoinPlan(pattern(0, 1, Term.unbound()), pattern(1, 2, Term.unbound())), new int[] { 0, 2 },
				COUNTS, null);
		assertNotNull(plan);
		NativeLmdbQuerySource source = mock(NativeLmdbQuerySource.class);
		NativeSlotLayout layout = new NativeSlotLayout(Map.of("a", 0, "j", 1, "b", 2), null);
		layout.freeze(List.of("a", "j", "b"));
		RowState row = new RowState(source, layout, EmptyBindingSet.getInstance());
		assertTrue(LmdbNativeAggregateCompiler.initializeRow(row, row.base, source, layout));
		assertFalse(plan.handles(row));
		when(source.hasCanonicalIds()).thenReturn(true);
		assertTrue(plan.handles(row));
		row.slots[1] = 100L;
		assertFalse(plan.handles(row));
		row.slots[1] = LmdbNativeAggregateCompiler.UNKNOWN;
		row.bindSummary(1, NativeResultCell.lexicalLength(3L));
		assertEquals(LmdbNativeAggregateCompiler.UNKNOWN, row.slots[1]);
		assertTrue((row.boundMask() & (1L << 1)) != 0L);
		assertFalse(plan.handles(row), "a bound physical summary is not an unbound RDF term slot");
	}

	@Test
	void onlyExactIntegerNecessaryHavingBoundsArePushed() {
		ValueFactory vf = SimpleValueFactory.getInstance();
		Compare greater = new Compare(new Var("count"), new ValueConstant(vf.createLiteral(7)), Compare.CompareOp.GT);
		assertEquals(8L, LmdbSparseJoinAggregatePlan.minimumCount(greater, COUNTS));
		Compare max = new Compare(new Var("count"), new ValueConstant(vf.createLiteral(Long.MAX_VALUE)),
				Compare.CompareOp.GT);
		assertEquals(Long.MAX_VALUE, LmdbSparseJoinAggregatePlan.minimumCount(max, COUNTS));
		Compare fractional = new Compare(new Var("count"), new ValueConstant(vf.createLiteral(7.5)),
				Compare.CompareOp.GE);
		assertEquals(1L, LmdbSparseJoinAggregatePlan.minimumCount(fractional, COUNTS));
		assertEquals(1L, LmdbSparseJoinAggregatePlan.minimumCount(new Or(greater, max), COUNTS));
	}

	private static PatternPlan pattern(int subject, int object, Term context) {
		return new PatternPlan(Term.slot(subject), Term.constant(42L), Term.slot(object), context,
				ContextConstraint.UNRESTRICTED, context.hasSlot(), 8D);
	}

	private static void restore(String property, String value) {
		if (value == null) {
			System.clearProperty(property);
		} else {
			System.setProperty(property, value);
		}
	}

